import sys, json
import pandas as pd
import numpy as np

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    df = pd.read_csv(sys.argv[1])
    facts = []

    # ---- TOTALS ----
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else np.nan
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_units_lw = df['Units_LW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)
    tot_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(tot_rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(tot_rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if pd.notna(tot_rev_ly):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(tot_rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    if tot_rev_lw and not pd.isna(tot_rev_lw) and tot_rev_lw != 0:
        wow = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if pd.notna(tot_rev_ly) and tot_rev_ly != 0:
        yoy = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(tot_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(tot_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(tot_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(tot_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    # ---- PER ENTITY ----
    df_sorted = df.copy()
    if 'Rank' in df_sorted.columns:
        df_sorted = df_sorted.sort_values('Rank', na_position='last')
    else:
        df_sorted = df_sorted.sort_values('Revenue_TW', ascending=False, na_position='last')

    for _, row in df_sorted.iterrows():
        entity = row['Entity']

        if pd.notna(row.get('Revenue_TW')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })

        if pd.notna(row.get('WoW_Pct')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "WoW",
                "value": to_float(row['WoW_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

        if pd.notna(row.get('YoY_Pct')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "YoY",
                "value": to_float(row['YoY_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": entity, "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Revenue_TW / sum(Revenue_TW) * 100"
            })

        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": entity, "metric": "rank", "period": "TW",
                "value": to_float(row['Rank'], 0),
                "formula": "Rank by Revenue_TW descending"
            })

    # Trim to 25 facts, keeping earliest (most important) ones
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
